"/* ==========================================================================
   TritonRegister - Modern University Course Registration Stylesheet
   Vibrant, Colorful, Accessible, Fully Responsive
   ========================================================================== */

:root {
  /* Vibrant Color Palette */
  --primary: #4f46e5;
  --primary-light: #6366f1;
  --primary-dark: #3730a3;
  --primary-glow: rgba(99, 102, 241, 0.25);

  --secondary: #06b6d4;
  --secondary-dark: #0891b2;
  --secondary-glow: rgba(6, 182, 212, 0.25);

  --accent-rose: #f43f5e;
  --accent-rose-light: #ffe4e6;
  --accent-emerald: #10b981;
  --accent-emerald-light: #d1fae5;
  --accent-amber: #f59e0b;
  --accent-amber-light: #fef3c7;
  --accent-purple: #8b5cf6;
  --accent-purple-light: #ede9fe;
  --accent-fuchsia: #d946ef;

  /* Gradients */
  --gradient-primary: linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #c026d3 100%);
  --gradient-cyan: linear-gradient(135deg, #0284c7 0%, #06b6d4 100%);
  --gradient-emerald: linear-gradient(135deg, #059669 0%, #10b981 100%);
  --gradient-amber: linear-gradient(135deg, #d97706 0%, #f59e0b 100%);
  --gradient-rose: linear-gradient(135deg, #e11d48 0%, #f43f5e 100%);
  --gradient-card-header: linear-gradient(135deg, #4338ca 0%, #6366f1 100%);

  /* Neutrals & Surfaces */
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-surface-elevated: #ffffff;
  --bg-input: #f8fafc;
  --bg-input-focus: #ffffff;

  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-dim: #94a3b8;
  --text-inverse: #ffffff;

  --border-light: #e2e8f0;
  --border-subtle: #cbd5e1;
  --border-focus: #6366f1;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
